'use client'

import type { ComponentProps, ReactNode } from 'react'
import {
  Select as UiSelect,
  SelectContent as UiSelectContent,
  SelectGroup as UiSelectGroup,
  SelectGroupLabel as UiSelectGroupLabel,
  SelectItem as UiSelectItem,
  SelectItemIndicator as UiSelectItemIndicator,
  SelectLabel as UiSelectLabel,
  SelectSeparator as UiSelectSeparator,
  SelectTrigger as UiSelectTrigger,
  SelectValue as UiSelectValue,
} from '@ui-sdk/react/select'

import './select.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

/**
 * Select, a 1:1 port of opencode's Select (`@opencode/ui`, MIT):
 * `packages/ui/src/forms/select` (`select-v2`).
 *
 * Styling lives in `select.css` as attribute rules (`data-appearance`,
 * `data-surface`, `data-invalid`, `data-numeric`, `data-open`,
 * `data-placeholder`, `data-highlighted`, `data-selected`, `data-disabled`),
 * so every trigger and item state — rest, hover, expanded, focus, invalid,
 * disabled, placeholder shown — matches upstream. Behaviour (open, keyboard
 * navigation and typeahead, selection, form value, ARIA wiring) comes from
 * `@ui-sdk/react`.
 *
 * Upstream's Select is single-select: it hardcodes `multiple={false}` on
 * Kobalte, and `select.css` has no multiple rules. ui-sdk does support
 * `multiple`, so Kitsaas exposes it as-is: the value becomes an array, the
 * list stays open while you toggle items, and `SelectValue` summarizes a long
 * selection (`maxLabels`, `getMoreLabel`). The summary styling is upstream's
 * value box, so it needs no new rules.
 *
 * Upstream renders the whole control as one component with a chevron and a
 * `Value` part. ui-sdk splits it into parts, so the trigger takes the chevron
 * itself and `SelectValue` carries upstream's value-text box:
 *
 *   <Select items={fruits} placeholder="Pick a fruit">
 *     <SelectLabel>Fruit</SelectLabel>
 *     <SelectTrigger>
 *       <SelectValue />
 *     </SelectTrigger>
 *     <SelectContent>
 *       <SelectItem value="apple">Apple</SelectItem>
 *     </SelectContent>
 *   </Select>
 */

export type SelectAppearance = 'inline' | 'small' | 'base' | 'large'
export type SelectSurface = 'base' | 'layer-1' | 'invisible'

type UiSelectProps = ComponentProps<typeof UiSelect>

export type SelectProps = UiSelectProps

export function Select(props: SelectProps) {
  return <UiSelect {...props} />
}

type UiSelectLabelProps = ComponentProps<typeof UiSelectLabel>

export type SelectLabelProps = Omit<UiSelectLabelProps, 'className' | 'render'> & {
  className?: UiSelectLabelProps['className']
  render?: UiSelectLabelProps['render']
}

export function SelectLabel(props: SelectLabelProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSelectLabel {...rest} className={props.className} render={props.render} />
}

type UiSelectTriggerProps = ComponentProps<typeof UiSelectTrigger>

export type SelectTriggerProps = Omit<
  UiSelectTriggerProps,
  'className' | 'render' | 'children'
> & {
  /** Defaults to `inline`, like opencode's select. */
  appearance?: SelectAppearance
  /** Fill of a field trigger; ignored by `inline`. Defaults to `base`. */
  surface?: SelectSurface
  /** Marks the outline and the value red, like upstream's `invalid`. */
  invalid?: boolean
  /** Applies tabular numerals to the value. */
  numeric?: boolean
  className?: UiSelectTriggerProps['className']
  render?: UiSelectTriggerProps['render']
  children?: UiSelectTriggerProps['children']
}

export function SelectTrigger(props: SelectTriggerProps) {
  const rest = omit(
    props,
    'appearance',
    'surface',
    'invalid',
    'numeric',
    'className',
    'render',
    'children',
  )

  const appearance = () => props.appearance ?? 'inline'

  return (
    <UiSelectTrigger
      {...rest}
      className={props.className}
      render={props.render}
      data-appearance={appearance()}
      data-surface={
        appearance() === 'inline' ? undefined : (props.surface ?? 'base')
      }
      data-invalid={props.invalid ? '' : undefined}
      data-numeric={props.numeric ? '' : undefined}
    >
      {(state) => (
        <>
          {typeof props.children === 'function'
            ? props.children(state)
            : (props.children ?? <SelectValue />)}
          <span data-slot="select-chevron" aria-hidden="true">
            <ChevronDown />
          </span>
        </>
      )}
    </UiSelectTrigger>
  )
}

type UiSelectValueProps = ComponentProps<typeof UiSelectValue>

export type SelectValueProps = Omit<UiSelectValueProps, 'className' | 'render'> & {
  className?: UiSelectValueProps['className']
  render?: UiSelectValueProps['render']
  /**
   * With `multiple`, how many labels to show before summarizing the rest.
   * Defaults to 2.
   */
  maxLabels?: number
  /** Writes the summary for the labels past `maxLabels`. Defaults to "N more". */
  getMoreLabel?: (count: number) => string
}

export function SelectValue(props: SelectValueProps) {
  const rest = omit(props, 'className', 'render', 'maxLabels', 'getMoreLabel')

  return (
    <span data-slot="select-trigger-value">
      <UiSelectValue
        {...rest}
        className={props.className}
        render={props.render}
        maxLabels={props.maxLabels ?? 2}
        getMoreLabel={props.getMoreLabel ?? ((count) => `${count} more`)}
      />
    </span>
  )
}

type UiSelectContentProps = ComponentProps<typeof UiSelectContent>

export type SelectContentProps = Omit<
  UiSelectContentProps,
  'className' | 'render'
> & {
  className?: UiSelectContentProps['className']
  render?: UiSelectContentProps['render']
}

export function SelectContent(props: SelectContentProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiSelectContent
      {...rest}
      className={props.className}
      render={props.render}
      data-scrollable
    />
  )
}

type UiSelectGroupProps = ComponentProps<typeof UiSelectGroup>

export type SelectGroupProps = Omit<UiSelectGroupProps, 'className' | 'render'> & {
  className?: UiSelectGroupProps['className']
  render?: UiSelectGroupProps['render']
}

export function SelectGroup(props: SelectGroupProps) {
  const rest = omit(props, 'className', 'render')

  return <UiSelectGroup {...rest} className={props.className} render={props.render} />
}

type UiSelectGroupLabelProps = ComponentProps<typeof UiSelectGroupLabel>

export type SelectGroupLabelProps = Omit<
  UiSelectGroupLabelProps,
  'className' | 'render'
> & {
  className?: UiSelectGroupLabelProps['className']
  render?: UiSelectGroupLabelProps['render']
}

export function SelectGroupLabel(props: SelectGroupLabelProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiSelectGroupLabel {...rest} className={props.className} render={props.render} />
  )
}

type UiSelectSeparatorProps = ComponentProps<typeof UiSelectSeparator>

export type SelectSeparatorProps = Omit<
  UiSelectSeparatorProps,
  'className' | 'render'
> & {
  className?: UiSelectSeparatorProps['className']
  render?: UiSelectSeparatorProps['render']
}

export function SelectSeparator(props: SelectSeparatorProps) {
  const rest = omit(props, 'className', 'render')

  return (
    <UiSelectSeparator {...rest} className={props.className} render={props.render} />
  )
}

type UiSelectItemProps = ComponentProps<typeof UiSelectItem>

export type SelectItemProps = Omit<
  UiSelectItemProps,
  'className' | 'render' | 'children'
> & {
  className?: UiSelectItemProps['className']
  render?: UiSelectItemProps['render']
  children?: UiSelectItemProps['children']
}

export function SelectItem(props: SelectItemProps) {
  const rest = omit(props, 'className', 'render', 'children')

  return (
    <UiSelectItem {...rest} className={props.className} render={props.render}>
      {(state) => (
        <>
          <span data-slot="menu-item-content">
            {typeof props.children === 'function'
              ? props.children(state)
              : props.children}
          </span>
          <UiSelectItemIndicator keepMounted>
            <span data-slot="menu-item-indicator">
              <CheckMark />
            </span>
          </UiSelectItemIndicator>
        </>
      )}
    </UiSelectItem>
  )
}

/** Upstream's chevron: points down at rest, up while the list is open. */
function ChevronDown(): ReactNode {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M11 9.5L8 6.5L5 9.5"
        stroke="currentColor"
        strokeWidth="1"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/** Upstream's check mark inside a selected item. */
function CheckMark(): ReactNode {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M3.53564 8.17857L6.39279 11.75L12.4642 4.25"
        stroke="currentColor"
        strokeWidth="1"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/*
 * 1:1 port of opencode's Select (`@opencode/ui`, MIT):
 * packages/ui/src/forms/select/select.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so rest / hover / expanded / focus / invalid / disabled, the
 * placeholder, the inline trigger and the item states all match
 * `data-component="select-v2"`:
 *
 *   [data-component="select-v2"]                 →  [data-slot="select-trigger"]
 *   [data-slot="select-v2-value"]                →  [data-slot="select-trigger-value"]
 *   [data-slot="select-v2-value-text"]           →  [data-slot="select-value"]  (ui-sdk's part)
 *   [data-slot="select-v2-chevron"]              →  [data-slot="select-chevron"]
 *   [data-component="menu-v2-content"]
 *     [data-slot="select-v2-content"]            →  [data-slot="select-content"]
 *   [data-slot="select-v2-listbox"]              →  [data-slot="select-content"]
 *                                                  (ui-sdk's content is the listbox)
 *   [data-component="menu-v2-item"]              →  [data-slot="select-item"]
 *   [data-slot="menu-v2-item-content"]           →  [data-slot="menu-item-content"]   (same rule as Menu)
 *   [data-slot="menu-v2-item-indicator"]         →  [data-slot="menu-item-indicator"] (same rule as Menu)
 *   [data-slot="menu-v2-group-label"]            →  [data-slot="select-group-label"]
 *   [data-slot="menu-v2-separator"]              →  [data-slot="select-separator"]
 *   [data-expanded]                              →  [data-open]  (ui-sdk's attribute)
 *   [data-placeholder-shown]                     →  [data-placeholder]
 *   [data-checked] on an item                    →  [data-selected]  (upstream mirrors selection
 *                                                  onto the listbox item's `data-selected`)
 *
 * The item's text and check glyph keep upstream's `menu-v2` slots
 * (`menu-item-content`, `menu-item-indicator`), so their rules stay in
 * `menu.css` and are reused unchanged: this file imports it, as upstream's
 * select.css imports menu.css. The item box, the vars it hands those slots,
 * the content surface and the group label / separator repeat the shared menu
 * declarations here with the same values, because ui-sdk gives Select's parts
 * slots of their own.
 *
 * Upstream wraps the popup in `[data-popper-positioner]` and raises that
 * wrapper with `z-index: 60`. ui-sdk renders the popup in place in the top
 * layer, with no positioner element, so the content is its own positioner and
 * keeps that z-index directly.
 *
 * Upstream's listbox sits inside its scroll viewport; ui-sdk's content is the
 * listbox itself, so the listed rules merge onto that one element and the
 * listbox's `width: 100%` is dropped: the popup is sized by the positioner
 * already. Upstream's trigger is a div with a hidden input, so `:focus-within`
 * matched its field; ui-sdk's trigger is the button itself and keeps the same
 * selector. Upstream styles no read-only state, so neither does this file.
 *
 * Not ported: `components/menu-scroll.css`. Its custom thumb belongs to
 * opencode's own scroll container, which ui-sdk has no part for; the content
 * keeps upstream's 12rem limit and scrolls natively. The sheet presentation
 * that ui-sdk can render has no upstream styling either.
 *
 * select.css has no [data-color-scheme="dark"] block upstream; the --v2-*
 * tokens flip with the scheme.
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 */

@import "./menu.css";

@layer components {
  /* ---------------------------------------------------------------- */
  /* Trigger                                                          */
  /* ---------------------------------------------------------------- */

  /* [data-component="select-v2"] — the field trigger. Upstream's root is a
     div; ui-sdk renders a button, so the button's UA font is reset. */
  [data-slot="select-trigger"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: row;
    align-items: stretch;
    padding-block: 0;
    padding-inline: 0 6px;
    gap: 8px;
    width: 280px;
    height: 28px;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    flex: none;
    align-self: stretch;
    user-select: none;
    font: inherit;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="select-trigger"][data-appearance="small"] {
    height: 24px;
  }

  [data-slot="select-trigger"][data-appearance="large"] {
    height: 32px;
    padding-inline: 0 8px;
  }

  [data-slot="select-trigger"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="select-trigger"][data-surface="invisible"] {
    background: transparent;
    box-shadow: none;
  }

  /* An inset overlay keeps the surface colour underneath, the same hover the
     text input uses. */
  @media (hover: hover) {
    [data-slot="select-trigger"]:where(:hover):not(
        [data-disabled],
        [data-invalid],
        [data-open],
        [data-appearance="inline"],
        [data-surface="invisible"]
      ):not(:focus-within) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }

    [data-slot="select-trigger"][data-surface="invisible"]:where(:hover):not(
        [data-disabled],
        [data-invalid],
        [data-open]
      ):not(:focus-within) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="select-trigger"]:where([data-open]):not(
      [data-disabled],
      [data-invalid],
      [data-appearance="inline"]
    ) {
    box-shadow:
      inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
      var(--v2-elevation-input);
    outline-color: transparent;
  }

  [data-slot="select-trigger"][data-surface="invisible"]:where([data-open]):not(
      [data-disabled],
      [data-invalid]
    ) {
    background: var(--v2-overlay-simple-overlay-hover);
    box-shadow: none;
  }

  [data-slot="select-trigger"]:where(:focus-within):not(
      [data-disabled],
      [data-invalid]
    ):not([data-open]) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="select-trigger"]:where([data-invalid]):not([data-disabled]) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
  }

  [data-slot="select-trigger"]:where([data-disabled]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ---------------------------------------------------------------- */
  /* Value and chevron                                                */
  /* ---------------------------------------------------------------- */

  [data-slot="select-trigger"] [data-slot="select-trigger-value"] {
    display: flex;
    flex-direction: row;
    align-items: center;
    align-self: stretch;
    padding: 0;
    min-width: 0;
    flex: 1 1 auto;
    min-height: 0;
    cursor: default;
  }

  [data-slot="select-trigger"] [data-slot="select-value"] {
    display: block;
    width: 100%;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    padding-block: 0;
    padding-inline: 8px 0;
    margin: 0;
    border: 0;
    background: transparent;
    outline: none;
    text-align: start;
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: 16px;
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
    cursor: default;
  }

  [data-slot="select-trigger"] [data-slot="select-value"][data-placeholder] {
    color: var(--v2-text-text-faint);
  }

  [data-slot="select-trigger"][data-numeric] [data-slot="select-value"] {
    font-variant-numeric: tabular-nums;
  }

  [data-slot="select-trigger"]:where([data-invalid]):not([data-disabled])
    [data-slot="select-value"] {
    color: var(--v2-state-fg-danger);
  }

  [data-slot="select-trigger"] [data-slot="select-chevron"] {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    align-self: center;
    flex: none;
    width: 20px;
    height: 20px;
    padding: 2px;
    gap: 3px;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--v2-icon-icon-muted);
    pointer-events: none;
  }

  /* Keyed to the chevron, not the trigger slot, so a trigger rendered as a Button keeps it. */
  [data-slot="select-chevron"] svg {
    display: block;
    flex: none;
    transform: rotate(180deg);
    transform-origin: 50% 50%;
  }

  [data-open] > [data-slot="select-chevron"] svg {
    transform: rotate(0deg);
  }

  /* ---------------------------------------------------------------- */
  /* Inline trigger, upstream's default                               */
  /* ---------------------------------------------------------------- */

  [data-slot="select-trigger"][data-appearance="inline"] {
    width: fit-content;
    max-width: 100%;
    height: 24px;
    padding-block: 4px;
    padding-inline: 8px 4px;
    gap: 4px;
    border-radius: 4px;
    background: transparent;
    box-shadow: none;
    outline: none;
    align-self: auto;
  }

  [data-slot="select-trigger"][data-appearance="inline"]:where(:hover):not(
      [data-disabled],
      [data-invalid]
    ):not(:focus-within):not([data-open]) {
    background: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="select-trigger"][data-appearance="inline"]:where([data-open]):not(
      [data-disabled],
      [data-invalid]
    ) {
    background: var(--v2-overlay-simple-overlay-hover);
    outline: none;
    box-shadow: none;
  }

  [data-slot="select-trigger"][data-appearance="inline"]:where(:active):not(
      [data-disabled],
      [data-invalid]
    ):not([data-open]) {
    background: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="select-trigger"][data-appearance="inline"]
    [data-slot="select-value"] {
    padding: 0;
    font-weight: 530;
  }

  [data-slot="select-trigger"][data-appearance="inline"]
    [data-slot="select-chevron"] {
    width: 16px;
    height: 16px;
    padding: 0;
  }

  /* ---------------------------------------------------------------- */
  /* Content: the menu surface and the listbox, on one element        */
  /* ---------------------------------------------------------------- */

  [data-slot="select-content"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    margin: 0;
    padding: 4px;
    min-width: 160px;
    max-width: 23rem;
    max-height: 12rem;
    list-style: none;
    white-space: nowrap;
    z-index: 60;
    pointer-events: auto;

    background: var(--v2-background-bg-layer-01);
    border-radius: 6px;
    box-shadow: var(--v2-elevation-floating);

    outline: none;

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
  }

  /* Upstream's `[data-scrollable]` viewport; the content is the scroller here. */
  [data-slot="select-content"][data-scrollable] {
    overflow-y: auto;
    overflow-x: hidden;
  }

  [data-slot="select-content"]:focus {
    outline: none;
  }

  [data-slot="select-content"] > *:not([role="presentation"], [role="none"])
    + *:not([role="presentation"], [role="none"]) {
    margin-top: 2px;
  }

  [data-slot="select-content"] > [data-slot="select-item"],
  [data-slot="select-content"] > [data-slot="select-group-label"] {
    flex: none;
  }

  /* ---------------------------------------------------------------- */
  /* Items                                                            */
  /* ---------------------------------------------------------------- */

  [data-slot="select-item"] {
    --menu-v2-fg: var(--v2-text-text-base);
    --menu-v2-fg-muted: var(--v2-text-text-faint);
    --menu-v2-fg-subtle: var(--v2-text-text-muted);
    --menu-v2-icon: var(--v2-icon-icon-base);
    --menu-v2-badge-bg: var(--v2-background-bg-layer-02);
    --menu-v2-badge-border: var(--v2-border-border-base);
    --menu-v2-hover: var(--v2-overlay-simple-overlay-hover);

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;

    box-sizing: border-box;
    display: flex;
    flex-shrink: 0;
    flex-direction: row;
    align-items: center;
    gap: 8px;
    height: 28px;
    padding: 0 12px;
    padding-inline-end: 6px;
    background: transparent;
    border-radius: 4px;
    outline: none;
    cursor: default;
    user-select: none;

    font-variation-settings: "slnt" 0;
    font-variant-numeric: tabular-nums;
    color: var(--menu-v2-fg);
  }

  [data-slot="select-item"][data-highlighted] {
    background: var(--menu-v2-hover);
  }

  /* A listbox marks selection with data-selected; the menu item CSS uses
     data-checked, so the selected look is mirrored here. */
  [data-slot="select-item"][data-selected] [data-slot="menu-item-content"] {
    font-weight: 440;
    color: var(--menu-v2-fg);
  }

  [data-slot="select-item"][data-selected] [data-slot="menu-item-indicator"] {
    color: var(--menu-v2-icon);
  }

  [data-slot="select-item"][data-selected]
    [data-slot="menu-item-indicator"]
    svg {
    visibility: visible;
  }

  [data-slot="select-item"]:not([data-selected])
    [data-slot="menu-item-indicator"]
    svg {
    visibility: hidden;
  }

  [data-slot="select-item"][data-disabled] {
    pointer-events: none;
    opacity: 0.5;
  }

  /* ---------------------------------------------------------------- */
  /* Group label and separator, from the shared menu rules            */
  /* ---------------------------------------------------------------- */

  [data-slot="select-group-label"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    height: 28px;
    padding: 0 12px;

    font-size: 11px;
    font-weight: 530;
    letter-spacing: 0.05px;
    color: var(--v2-text-text-faint);
    user-select: none;
    font-variant-numeric: tabular-nums;
  }

  [data-slot="select-separator"] {
    flex: none;
    height: 1px;
    width: calc(100% + 4px);
    margin: 2px -2px;
    background: var(--v2-border-border-muted);
    border: none;
  }
}
